function drawText(str, x, y, color, scale = 1, center = false) {
  str = String(str).toUpperCase();
  let total = 0;
  for (let i = 0; i < str.length; i++) total += 4;
  total -= 1;
  let cx = center ? Math.floor(x - (total * scale) / 2) : x;
  ctx.fillStyle = color;
  for (let i = 0; i < str.length; i++) {
    const map = FONT[str[i]] || FONT['?'];
    for (let r = 0; r < 5; r++) {
      for (let c = 0; c < 3; c++) {
        if (map[r][c] === '#') {
          ctx.fillRect(cx + c * scale, y + r * scale, scale, scale);
        }
      }
    }
    cx += 4 * scale;
  }
}

