function drawSprite(map, x, y, palette) {
  const h = map.length;
  const w = map[0].length;
  const ox = Math.floor(x - w / 2);
  const oy = Math.floor(y - h / 2);
  for (let r = 0; r < h; r++) {
    const row = map[r];
    for (let c = 0; c < row.length; c++) {
      const ch = row[c];
      if (ch !== '.') {
