function buildSlots() {
  slots = [];
  const bossX = [88, 104, 120, 136];
  for (const x of bossX) slots.push({ type: 'boss', x, y: 36 });

  const goeiX = [56, 72, 88, 104, 120, 136, 152, 168];
  for (const y of [52, 68]) {
    for (const x of goeiX) slots.push({ type: 'goei', x, y });
  }

  const zakoX = [40, 56, 72, 88, 104, 120, 136, 152, 168, 184];
  for (const y of [84, 100]) {
    for (const x of zakoX) slots.push({ type: 'zako', x, y });
  }
}

function formationPos(e) {
  const slot = e.slot;
  const cx = W / 2;
  const cy = 68;
  const sway = Math.sin(frame * 0.02) * 10;
  const scale = formationDone ? 1 + Math.sin(frame * 0.015) * 0.06 : 1;
  return {
    x: cx + (slot.x - cx) * scale + sway,
    y: slot.y + (formationDone ? Math.sin(frame * 0.015) * 2 : 0)
  };
}

// ---------------------------------------------------------------------------
// Entry paths
// ---------------------------------------------------------------------------

function makeEntryPath(slot, group, idx) {
  const off = idx * 4 - 14;
  let p0, p1, p2;
  const p3 = { x: slot.x, y: slot.y };

  switch (group % 5) {
    case 0:
      p0 = { x: -20, y: 20 + off };
      p1 = { x: 60, y: 120 + off };
      p2 = { x: 180, y: 20 + off };
      break;
    case 1:
      p0 = { x: W + 20, y: 20 + off };
      p1 = { x: 164, y: 120 + off };
      p2 = { x: 44, y: 20 + off };
      break;
    case 2:
      p0 = { x: -20, y: H + 16 + off };
      p1 = { x: 80, y: 220 + off };
      p2 = { x: 180, y: 80 + off };
      break;
    case 3:
      p0 = { x: W + 20, y: H + 16 + off };
      p1 = { x: 144, y: 220 + off };
      p2 = { x: 44, y: 80 + off };
      break;
    default:
      p0 = { x: W / 2 + off, y: -20 };
      p1 = { x: 40, y: 140 + off };
      p2 = { x: 184, y: 140 + off };
      break;
  }
  return { p0, p1, p2, p3 };
}

function makeDivePath(e, targetX, endY) {
  return {
    p0: { x: e.x, y: e.y },
    p1: { x: e.x + rand(-45, 45), y: e.y + 40 },
    p2: { x: targetX + rand(-45, 45), y: 180 },
    p3: { x: targetX, y: endY }
  };
}

function startReturn(e) {
  e.state = 'returning';
  e.t = 0;
  const fp = formationPos(e);

  if (e.y < H - 10) {
    e.returnPath = {
      p0: { x: e.x, y: e.y },
      p1: { x: e.x, y: e.y - 40 },
      p2: { x: fp.x, y: fp.y },
      p3: { x: fp.x, y: fp.y }
    };
  } else {
    const sx = clamp(e.x, -16, W + 16);
    e.returnPath = {
      p0: { x: sx, y: -16 },
      p1: { x: sx, y: 60 },
      p2: { x: fp.x, y: fp.y },
      p3: { x: fp.x, y: fp.y }
    };
  }
}

