function createEnemy(type, slot, group, idx, delay) {
  return {
    id: nextId++,
    type,
    slot,
    x: slot.x,
    y: slot.y,
    state: 'entering',
    t: 0,
    delay,
    path: makeEntryPath(slot, group, idx),
    health: type === 'boss' ? 2 : 1,
    anim: 0,
    animTimer: 0,
    fireTimer: randInt(80, 260),
    escortIds: [],
    captive: null,
    hitFlash: 0,
    tractor: false,
    beamTimer: 0,
    beamDuration: 120,
    challenge: false,
    counted: false
