}

function createChallengeEnemy(wave, idx) {
  const types = ['zako', 'zako', 'goei', 'goei', 'boss'];
  const type = types[(wave + idx) % types.length];
  const slot = { type, x: W / 2, y: 40 };
  const side = (wave + idx) % 2;
  const p0 = side === 0
    ? { x: -20, y: 20 + idx * 10 }
    : { x: W + 20, y: 20 + idx * 10 };

  return {
    id: nextId++,
    type,
    slot,
    x: p0.x,
    y: p0.y,
    state: 'challenge',
    t: 0,
    delay: idx * 5,
    path: {
      p0,
      p1: { x: W / 2 + Math.sin(idx * 1.7) * 70, y: 100 },
      p2: { x: W / 2 - Math.cos(idx * 1.1) * 70, y: 180 },
      p3: { x: W / 2 + Math.sin(idx * 2.3) * 50, y: H + 30 }
    },
    health: 1,
    anim: 0,
    animTimer: 0,
    fireTimer: 9999,
    escortIds: [],
    captive: null,
    hitFlash: 0,
    challenge: true,
    counted: false
  };
}

function buildFormation() {
  buildSlots();
  enemies = [];
  for (let i = 0; i < slots.length; i++) {
    const group = Math.floor(i / 8);
    const idx = i % 8;
    const delay = group * 65 + idx * 3;
    enemies.push(createEnemy(slots[i].type, slots[i], group, idx, delay));
  }
}

function startGame() {
  score = 0;
  reserve = 2;
  nextExtra = 20000;
  shotsFired = 0;
  shotsHit = 0;
  stage = 1;
  player.alive = true;
  player.dual = false;
  player.x = W / 2;
  player.y = 250;
  player.invuln = 60;
  player.respawnTimer = 0;
  player.capturing = false;
  startStage(stage);
}

